          y: memory.y,
          source: shared ? `radio-${memory.source}` : memory.source,
          confidence,
          enemyKey: memory.enemyKey || '',
          vx: Number(memory.vx) || 0,
          vy: Number(memory.vy) || 0,
          shared,
          age
