      const left = bearing - Math.PI / 2;
      const right = bearing + Math.PI / 2;
      const leftClear = clearanceAlong(this.x, this.y, left, 1.35, BOT_RADIUS + 0.01);
      const rightClear = clearanceAlong(this.x, this.y, right, 1.35, BOT_RADIUS + 0.01);
