        mat4TRS(glModel, slat.x, 0.017, slat.z, grate.yaw, 0, 0, 0.014, 0.012, 0.23);
        drawMesh(glMeshes.cube, [0.30, 0.34, 0.35], glModel, 0, 1, 3, 0.22);
