      'VX-7':       { length: 1.00, handguard: 1.00, barrel: 0.98, stock: 0.92, optic: 0, mag: 0.92, accent: [0.18, 0.30, 0.36], holdX: 0.00, holdY: 0.00, holdZ: 0.00, pitchBias: 0.000, rollBias: 0.000, foregrip: 0, opticHeight: 1.00 },
