      const drafted = changePlayerStatDraft(player.id, stat, 1);
      const saved = drafted ? savePlayerStatDraft(player.id) : false;
      return { ok: drafted && saved, before, after: { points: player.unspentPoints, value: player.stats?.[stat] } };
