        const drawDecision = careerRoundDecision({ supportedTime: 30, isolatedTime: 30, shotsFired: 16, shotsHit: 6, tradeAttempts: 1, tradeKills: 0, damageDealt: 210, damageTaken: 210, survivors: 1 }, null);
