        roundFreezeTimer = 0;
        const observations = new Map(bots.map(bot => [bot, { maxElevation: arenaElevationAt(bot.x, bot.y, 'summit'), zones: new Set([levelZoneAt(bot.x, bot.y)?.short || '']), aliveAtEnd: true }]));
        const dt = 1 / 60;
