        bot.lateRoundTargetKey = '';
        bot.lateRoundTargetUntil = 0;
        bot.navTrail = [{ x: bot.x, y: bot.y, cell: keyOf(Math.floor(bot.x), Math.floor(bot.y)), at: simulationClock }];
